import{_ as t,o,c as i,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Competitive Intelligence — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"competitive-intel-01-overview-and-concepts.md","filePath":"competitive-intel-01-overview-and-concepts.md"}'),r={name:"competitive-intel-01-overview-and-concepts.md"};function a(s,e,c,l,p,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="competitive-intelligence-—-overview-concepts" tabindex="-1">Competitive Intelligence — Overview &amp; Concepts <a class="header-anchor" href="#competitive-intelligence-—-overview-concepts" aria-label="Permalink to &quot;Competitive Intelligence — Overview &amp; Concepts&quot;">​</a></h1><p><em>What it is, why it matters, and how it fits into Lodestone</em></p><hr><h2 id="what-is-competitive-intelligence" tabindex="-1">What Is Competitive Intelligence? <a class="header-anchor" href="#what-is-competitive-intelligence" aria-label="Permalink to &quot;What Is Competitive Intelligence?&quot;">​</a></h2><p>The Competitive Intelligence module (labeled <strong>Intel</strong> in the navigation) is Lodestone&#39;s built-in system for tracking your competitors and generating AI-powered market insight reports. It keeps you and your team informed about the competitive landscape without requiring manual research.</p><p>Instead of periodically Googling your competitors or relying on sales to surface competitive signals, Competitive Intelligence delivers structured, AI-generated reports on a schedule you define — covering competitor activity, market positioning, and emerging trends in your space.</p><hr><h2 id="why-it-exists" tabindex="-1">Why It Exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to &quot;Why It Exists&quot;">​</a></h2><p>Competitive awareness erodes quickly without a system. A team that reviewed its competitors six months ago may be missing significant shifts in the market today — new features shipped, pricing changes, positioning pivots, or new entrants.</p><p>The Competitive Intelligence module fixes this by making competitive monitoring automatic and regular. You define your competitors once. Lodestone generates reports on your schedule. The signal stays fresh without manual effort.</p><p>Beyond keeping you informed, there is a direct connection to product planning: competitive intelligence reports can feed the Extracts module, allowing insights from market analysis to flow directly into your feature backlog.</p><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="competitors" tabindex="-1">Competitors <a class="header-anchor" href="#competitors" aria-label="Permalink to &quot;Competitors&quot;">​</a></h3><p>A competitor is a named company or product you want to track. You add competitors manually by name and optional website, or use AI-assisted suggestions based on your industry description. Competitors are the lens through which all reports are generated.</p><h3 id="intelligence-reports" tabindex="-1">Intelligence Reports <a class="header-anchor" href="#intelligence-reports" aria-label="Permalink to &quot;Intelligence Reports&quot;">​</a></h3><p>A report is an AI-generated document that analyzes your competitors&#39; public activity and positions it in the context of your market. Each report covers the competitors you have on record at the time it is generated. Reports have a status:</p><ul><li><strong>Generating</strong> — the AI is currently producing the report</li><li><strong>Completed</strong> — the report is ready to read and download</li><li><strong>Failed</strong> — generation did not complete; a new report can be generated</li></ul><h3 id="report-generation" tabindex="-1">Report Generation <a class="header-anchor" href="#report-generation" aria-label="Permalink to &quot;Report Generation&quot;">​</a></h3><p>Reports are generated on demand or on a recurring schedule. When you generate a report, Lodestone uses your competitor list and your organization&#39;s industry description to produce structured analysis. Generation typically takes a few minutes.</p><h3 id="industry-description" tabindex="-1">Industry Description <a class="header-anchor" href="#industry-description" aria-label="Permalink to &quot;Industry Description&quot;">​</a></h3><p>Your industry description is the context the AI uses to frame competitive analysis. A specific, accurate description produces more relevant output. It is set in the Competitive Intelligence settings and is separate from the Organization Description used by Documents.</p><h3 id="report-schedule" tabindex="-1">Report Schedule <a class="header-anchor" href="#report-schedule" aria-label="Permalink to &quot;Report Schedule&quot;">​</a></h3><p>Reports can be generated automatically on a weekly or biweekly basis, on a day of the week you choose. This keeps your competitive picture current without requiring manual triggering.</p><hr><h2 id="connecting-intel-to-planning" tabindex="-1">Connecting Intel to Planning <a class="header-anchor" href="#connecting-intel-to-planning" aria-label="Permalink to &quot;Connecting Intel to Planning&quot;">​</a></h2><p>One of the most powerful features of the Competitive Intelligence module is the ability to extract product ideas from a completed report. When you open a completed report, you can send it to the Extracts module for AI analysis — just as you would a meeting transcript. The AI surfaces feature ideas, problems, and opportunities found in the competitive analysis, which then appear in your extract queue for review.</p><p>This closes the loop between market intelligence and product planning:</p><blockquote><p>Competitor ships a new feature → Lodestone generates a report → You extract feature ideas from the report → Ideas flow into your backlog</p></blockquote><p>Extracts surfaced from competitive intelligence reports carry an <strong>Intel Report</strong> source badge, distinguishing them from transcript-sourced ideas.</p><hr><h2 id="how-competitive-intelligence-relates-to-the-rest-of-lodestone" tabindex="-1">How Competitive Intelligence Relates to the Rest of Lodestone <a class="header-anchor" href="#how-competitive-intelligence-relates-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Competitive Intelligence Relates to the Rest of Lodestone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Extracts</td><td>Completed reports can be fed to Extracts for AI analysis, surfacing feature ideas with an Intel Report source badge.</td></tr><tr><td>Features</td><td>Intel-sourced Extracts, when accepted, become Features in the backlog — just like transcript-sourced ones.</td></tr><tr><td>Settings</td><td>Industry description and report schedule are configured in the Competitive Intelligence settings panel.</td></tr></tbody></table><hr><h2 id="who-can-use-competitive-intelligence" tabindex="-1">Who Can Use Competitive Intelligence <a class="header-anchor" href="#who-can-use-competitive-intelligence" aria-label="Permalink to &quot;Who Can Use Competitive Intelligence&quot;">​</a></h2><p>Any workspace member can view reports, add competitors, and generate reports. Configuring the report schedule and industry description is available to all members from within the module&#39;s Settings panel.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for adding competitors, generating reports, and extracting features from reports.</em></p>',38)])])}const m=t(r,[["render",a]]);export{u as __pageData,m as default};
